public void Increment()
{
    int current = _counter; // Thread A reads 5
    current++;               // Thread B also reads 5
    _counter = current;      // Thread A writes 6
                            // Thread B writes 6 (A's increment lost)
}

private int _counter = 0;

public void Increment()
{
    // Atomically reads, increments, and writes in one CPU instruction
    Interlocked.Increment(ref _counter);
}

public int GetAndAdd(int delta)
{
    // Atomically returns current value and adds delta
    return Interlocked.Add(ref _counter, delta);
}
